using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class JohnSteinbeck
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "We are lonesome animals. We spend all our life trying to be less lonesome.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The discipline of the written word punishes both stupidity and dishonesty.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "In every bit of honest writing in the world ... there is a base theme. Try to understand men, if you understand each other you will be kind to each other. Knowing a man well never leads to hate and nearly always leads to love. There are shorter means, many of them. There is writing promoting social change, writing punishing injustice, writing in celebration of heroism, but always that base theme. Try to understand each other.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The death of children by starvation in our valleys is simply staggering. ... I'll do what I can. ... Funny how mean and little books become in the face of such tragedies.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Oh! the incidents all happened but — I'm not telling as much of the truth about them as I know. In satire you have to restrict the picture and I just can't do satire. I've written three books now that were dishonest because they were less than the best that I could do. One you never saw because I burned it the day I finished it. ... My whole work drive has been aimed at making people understand each other and then I deliberately write this book, the aim of which is to cause hatred through partial understanding. My father would have called it a smart-aleck book. It was full of tricks to make people ridiculous. If I can't do better I have slipped badly. And that I won't admit — yet.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is a nice thing to be working and believing in my work again. I hope I can keep the drive. I only feel whole and well when it is this way.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "For the first time I am working on a book that is not limited and that will take every bit of experience and thought and feeling that I have.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Boileau said that Kings, Gods and Heroes only were fit subjects for literature. The writer can only write about what he admires. Present-day kings aren't very inspiring, the gods are on a vacation and about the only heroes left are the scientists and the poor … And since our race admires gallantry, the writer will deal with it where he finds it. He finds it in the struggling poor now.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Ideas are like rabbits. You get a couple and learn how to handle them, and pretty soon you have a dozen.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "No little appetite or pain, no carelessness or meanness in him escaped her; no thought or dream or longing in him ever reached her. And yet several times in her life she had seen the stars.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I have come to believe that a great teacher is a great artist and that there are as few as there are any other great artists. It might even be the greatest of the arts since the medium is the human mind and spirit.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "One man was so mad at me that he ended his letter: “Beware. You will never get out of this world alive.”", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Writers are a little below clowns and a little above trained seals.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The profession of book-writing makes horse-racing seem like a solid, stable business.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Unless a reviewer has the courage to give you unqualified praise, I say ignore the bastard.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "He sings the songs of a people and I suspect that he is, in a way, that people. Harsh voiced and nasal, his guitar hanging like a tire iron on a rusty rim, there is nothing sweet about Woody, and there is nothing sweet about the songs he sings. But there is something more important for those who will listen. There is the will of the people to endure and fight against oppression. I think we call this the American spirit.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "This is the story of Danny and of Danny’s friends and of Danny’s house.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Ah, the prayers of the millions, how they must fight and destroy each other on their way to the throne of God.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "If two generous paths branch from the highroad of life and only one can be followed, who is to judge which is best?", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is a time of quiet joy, the sunny morning. When the glittery dew is on the mallow weeds, each leaf holds a jewel which is beautiful if not valuable. This is no time for hurry or for bustle. Thoughts are slow and deep and golden in the morning.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The story was gradually taking shape. Pilon liked it this way. It ruined a story to have it all come out quickly. The good story lay in half-told things which must be filled in out of the hearer’s own experience.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The candle aimed its spear of light at heaven, like an artist who consumes himself to become divine.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is astounding to find that the belly of every black and evil thing is as white as snow. And it is saddening to discover how the concealed parts of angels are leprous.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Ghosts could walk freely tonight, without fear of the disbelief of men; for this night was haunted, and it would be an insensitive man who did not know it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is worth while to be kind and generous,” he said. “Not only do such actions pile up a house of joy in Heaven; but there is, too, a quick reward here on earth. One feels a golden warmth glowing like a hot enchilada in one’s stomach.”", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "What pillow can one have like a good conscience?", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It was a glorious game. Theft robbed of the stigma of theft, crime altruistically committed—what is more gratifying?", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Beans are a roof over your stomach. Beans are a warm cloak against economic cold.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Time is more complex near the sea than in any other place, for in addition to the circling of the sun and the turning of the seasons, the waves beat out the passage of time on the rocks and the tides rise and fall as a great clepsydra.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Death is a personal matter, arousing sorrow, despair, fervor, or dry-hearted philosophy. Funerals, on the other hand, are social functions. Imagine going to a funeral without first polishing the automobile. Imagine standing at a graveside not dressed in your best dark suit and your best black shoes, polished delightfully. Imagine sending flowers to a funeral with no attached card to prove you had done the correct thing. In no social institution is the codified ritual of behavior more rigid than in funerals. Imagine the indignation if the minister altered his sermon or experimented with facial expression. Consider the shock if, at the funeral parlors, any chairs were used but those little folding yellow torture chairs with the hard seats. No, dying, a man may be loved, hated, mourned, missed; but once dead he becomes the chief ornament of a complicated and formal social celebration.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Ain't many guys travel around together. I don’t know why. Maybe ever’body in the whole damn world is scared of each other.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "His ear heard more than is said to him, and his slow speech had overtones not of thought, but of understanding beyond thought.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Guy don't need no sense to be a nice fella. Seems to me sometimes it jus' works the other way around. Take a real smart guy and he ain't hardly ever a nice fella.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Books ain't no good. A guy needs somebody — to be near him. A guy goes nuts if he ain't got nobody.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "They come, an' they quit an' go on; an' every damn one of 'em's got a little piece of land in his head. An' never a God damn one of 'em ever gets it. Just like heaven. Ever'body wants a little piece of lan'. I read plenty of books out here. Nobody never gets to heaven, and nobody gets no land. It's just in their head.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I seen too many guys with land in their head. They never get none under their hand.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Cannery Row in Monterey in California is a poem, a stink, a grating noise, a quality of light, a tone, a habit, a nostalgia, a dream.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The things we admire in men, kindness and generosity, openness, honesty, understanding and feeling are the concomitants of failure in our system. And those traits we detest, sharpness, greed, acquisitiveness, meanness, egotism and self-interest are the traits of success.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "There aren't very many of them in the world, as everyone finds out sooner or later.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "He was never alone. His business was conducted by groups of men like himself who joined together in clubs so that no foreign element or idea could enter. His religious life was again his lodge and his church, both of which were screened and protected. One night a week he played poker with men so exactly like himself that the game was fairly even, and from this fact his group was convinced that they were very fine poker players. Wherever he went he was not one man but a unit in a corporation, a unit in a club, in a lodge, in a church, in a political party. His thoughts and ideas were never subjected to criticism since he willingly associated only with people like himself. He read a newspaper written by and for his group. The books that came into his house were chosen by a committee which deleted material that might irritate him. He hated foreign countries and foreigners because it was difficult to find his counterpart in them. He did not want to stand out from his group. He would like to have risen to the top of it and be admired by it; but it would not occur to him to leave it. At occasional stags where naked girls danced on the tables and sat in great glasses of wine, Mr. Pritchard howled with laughter and drank the wine, but five hundred Mr. Pritchards were there with him.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Having few actual perceptions, she lived by rules. Education is good. Self-control is necessary. Everything in its time and place. Travel is broadening. And it was this last axiom which had forced her finally on the vacation to Mexico.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "But there was another reason too. She loved him. She really did. And he knew it. And you can't leave a thing like that. It's a structure and it has an architecture, and you can't leave it without tearing off a piece of yourself. So if you want to remain whole you stay no matter how much you may dislike staying. Juan was not a man who fooled himself very much.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "She envied Camille. Camille was a tramp, Mildred thought. And things were so much easier for a tramp. There was no conscience, no sense of loss, nothing but a wonderful, relaxed, stretching-cat selfishness. She could go to bed with anyone she wanted to and never see him again and have no feeling of loss or insecurity about it. That was the way Mildred thought it was with Camille. She wished she could be that way, and she knew she couldn't. Couldn't because of her mother. And the unbidden thought entered her mind—if her mother were only dead Mildred's life would be so much simpler. She could have a secret little place to live somewhere. Almost fiercely, she brushed the thought away. \"What a foul thing to think,\" she said to herself ceremoniously. But it was a dream she often had.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "For it is said that humans are never satisfied, that you give them one thing and they want something more. And this is said in disparagement, whereas it is one of the greatest talents the species has and one that has made it superior to animals that are satisfied with what they have.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A plan is a real thing, and things projected are experienced. A plan once made and visualized becomes a reality along with other realities—never to be destroyed but easily to be attacked.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Luck, you see, brings bitter friends.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "For every man in the world functions to the best of his ability, and no one does less than his best, no matter what he may think about it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "He had said, \"I am a man,\" and that meant certain things to Juana. It meant that he was half insane and half god. It meant that Kino would drive his strength against a mountain and plunge his strength against the sea. Juana, in her woman's soul, knew that the mountain would stand while the man broke himself; that the sea would surge while the man drowned in it. And yet it was this thing that made him a man, half insane and half god, and Juana had need of a man; she could not live without a man. Although she might be puzzled by these differences between man and woman, she knew them and accepted them and needed them. Of course she would follow him, there was no question of that. Sometimes the quality of woman, the reason, the caution, the sense of preservation, could cut through Kino's manness and save them all.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "When you argue with a child,\" she said warmly, \"you give a good argument and the child says yah, yah! You understand him and he doesn't listen, so the child wins.\"", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Victor's unfortunate choice it was always to mis-see, to mis-hear, to misjudge. He read softness into her because of the softness of her voice, when she was only remembering. His was the self-centered chaos of childhood. All looks and thoughts, loves and hatreds, were directed at him. Softness was softness towards him, weakness was weakness in the face of his strength. He preheard answers and listened not. He was full-coloured and brilliant—all outside of him was pale.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "He brought his malformed wisdom, his pool-hall, locker-room, joke-book wisdom to the front.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Mordeen said: \"I used to wonder why this love seemed sweeter than I had ever known, better than many people ever know. And then one day the reason came to me. There are very few great Anythings in the world. In work and art and emotion—the great is very rare. And I have one of the great and beautiful. Now say your yah, yah, Victor, like a child unanswerably answering Wisdom. You will have to do that, I think.\"", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "His guard was up now and he wasn't listening; he was only angry because here was a world he could not enter and so he had to disbelieve in its existence. He fell back on the world he knew.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "\"I do understand. I understand that you are offered a loveliness and you vomit on it, that you have the gift of love given you such as few men have ever known and you throw on it the acid of your pride, your ugly twisted sense of importance.\"", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "\"It is so easy a thing to give—only great men have the courage and courtesy and, yes, the generosity to receive.\"", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "\"Let us go,\" we said, \"into the Sea of Cortez, realizing that we become forever a part of it; that our rubber boots slogging through a flat of eel-grass, that the rocks we turn over in a tide pool, make us truly and permanently a factor in the ecology of the region. We shall take something away from it, but we shall leave something too.\" And if we seem a small factor in a huge pattern, nevertheless it is of relative importance. We take a tiny colony of soft corals from a rock in a little water world. And that isn't terribly important to the tide pool. Fifty miles away the Japanese shrimp boats are dredging with overlapping scoops, bringing up tons of shrimps, rapidly destroying the species so that it may never come back, and with the species destroying the ecological balance of the whole region. That isn't very important in the world. And thousands of miles away the great bombs are falling and the stars are not moved thereby. None of it is important or all of it is.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "In a modern scene, when the horizons stretch out and your philosopher is likely to fall off the world like a Dark Age mariner, he can save himself by establishing a taboo-box which he may call \"mysticism\" or \"supernaturalism\" or \"radicalism.\" Into this box he can throw all those thoughts which frighten him and thus be safe from them.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "We are no better than the animals; in fact in a lot of ways we aren't as good.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "There is a strange duality in the human which makes for an ethical paradox. We have definitions of good qualities and of bad; not changing things, but generally considered good and bad throughout the ages and throughout the species. Of the good, we think always of wisdom, tolerance, kindliness, generosity, humility; and the qualities of cruelty, greed, self-interest, graspingness, and rapacity are universally considered undesirable. And yet in our structure of society, the so-called and considered good qualities are invariable concomitants of failure, while the bad ones are the cornerstones of success. A man — a viewing-point man — while he will love the abstract good qualities and detest the abstract bad, will nevertheless envy and admire the person who though possessing the bad qualities has succeeded economically and socially, and will hold in contempt that person whose good qualities have caused failure. When such a viewing-point man thinks of Jesus or St. Augustine or Socrates he regards them with love because they are the symbols of the good he admires, and he hates the symbols of the bad. But actually he would rather be successful than good. In an animal other than man we would replace the term “good” with “weak survival quotient” and the term “bad” with “strong survival quotient.” Thus, man in his thinking or reverie status admires the progression toward extinction, but in the unthinking stimulus which really activates him he tends toward survival. Perhaps no other animal is so torn between alternatives. Man might be described fairly adequately, if simply, as a two-legged paradox. He has never become accustomed to the tragic miracle of consciousness. Perhaps, as has been suggested, his species is not set, has not jelled, but is still in a state of becoming, bound by his physical memories to a past of struggle and survival, limited in his futures by the uneasiness of thought and consciousness.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Men do change, and change comes like a little wind that ruffles the curtains at dawn, and it comes like the stealthy perfume of wildflowers hidden in the grass.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is a common experience that a problem difficult at night is resolved in the morning after the committee of sleep has worked on it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "No one knows how greatness comes to a man. It may lie in his blackness, sleeping, or it may lance into him like those driven fiery particles from outer space. These things, however, are known about greatness: need gives it life and puts it in action; it never comes without pain; it leaves a man changed, chastened, and exalted at the same time — he can never return to simplicity.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Power does not corrupt. Fear corrupts, perhaps fear of a loss of power.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is the misfortune of men to want to do a thing well, even a thing they do not want to do at all.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The one thing our species is helpless against is good fortune. It first puzzles, then frightens, then angers, and finally destroys us.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I wonder how many people I’ve looked at all my life and never seen.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It’s so much darker when a light goes out than it would have been if it had never shone.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I shall revenge myself in the cruelest way you can imagine. I shall forget it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Can you honestly love a dishonest thing?", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "People who are most afraid of their dreams convince themselves they don’t dream at all.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I guess I’m trying to say, Grab anything that goes by. It may not come around again.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The incident seemed to prove to me that intentions, good or bad, are not enough.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "When a condition or a problem becomes too great, humans have the protection of not thinking about it. But it goes inward and minces up with a lot of other things already there and what comes out is discontent and uneasiness, guilt and a compulsion to get something—anything—before it is all gone.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Farewell has a sweet sound of reluctance. Good-by is short and final, a word with teeth sharp to bite through the string that ties past to the future.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "We can shoot rockets into space but we can’t cure anger or discontent.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "For the most part people are not curious except about themselves.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Failure is a state of mind. It’s like one of those sand traps an ant lion digs. You keep sliding back. Takes one hell of a jump to get out of it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Are cats strange animals or do they so resemble us that we find them curious as we do monkeys?", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "If you want to keep a friend never test him.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "You know most people live ninety per cent in the past, seven per cent in the present, and that only leaves them three per cent for the future.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Only God sees the sparrow fall, but even God doesn’t do anything about it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "My dreams are the problems of the day stepped up to absurdity, a little like men dancing, wearing the horns and masks of animals.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is odd how a man believes he can think better in a special place. I have such a place, have always had it, but I know it isn't thinking I do there, but feeling and experiencing and remembering. It's a safety place — everyone must have one, although I never heard a man tell of it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "They successfully combined piracy and puritanism, which aren't so unlike when you come right down to it. Both had a strong dislike for opposition and both had a roving eye for other people's property.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Sometimes it's great fun to be silly, like children playing statues and dying of laughter. And sometimes being silly breaks the even pace and lets you get a new start.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "No man really knows about other human beings. The best he can do is to suppose that they are like himself.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Does anyone ever know even the outer fringe of another? What are you like in there? Mary — do you hear? Who are you in there?", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "When two people meet, each one is changed by the other so you've got two new people. Maybe that means — hell, it's complicated.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A man who tells secrets or stories must think of who is hearing or reading, for a story has as many versions as it has readers.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I guess we're all, or most of us, the wards of that nineteenth-century science which denied existence to anything it could not measure or explain. The things we couldn't explain went right on but surely not with our blessing. We did not see what we couldn't explain, and meanwhile a great part of the world was abandoned to children, insane people, fools, and mystics, who were more interested in what is than in why it is. So many old and lovely things are stored in the world's attic, because we don't want them around us and we don't dare throw them out.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "What a wonderful thing a woman is. I can admire what they do even if I don't understand why.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Even if teen-age children aren't making a sound, it's quieter when they're gone. They put a boiling in the air around them. As they left, the whole house seemed to sigh and settle. No wonder poltergeists infest only houses with adolescent children.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "What a frightening thing is the human, a mass of gauges and dials and registers, and we can read only a few and those perhaps not accurately.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A little hope, even hopeless hope, never hurt anybody.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Can you disbelieve in something you don't know about? ... It isn't that I don't believe but that I don't know.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "To be alive at all is to have scars.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "No one wants advice — only corroboration.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "In poverty she is envious. In riches she may be a snob. Money does not change the sickness, only the symptoms.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "In the dusk I saw her smile, that incredible female smile. It is called wisdom but it isn't that but rather an understanding that makes wisdom unnecessary.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The misery stayed, not thought about but aching away, and sometimes I would have to ask myself, Why do I ache? Men can get used to anything, but it takes time.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "There's something desirable about anything you're used to as opposed to something you're not.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "You know how advice is. You only want it if it agrees with what you wanted to do anyway.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "All men are moral. Only their neighbors are not.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A man is a lonely thing.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Maybe not having time to think is not having the wish to think.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Strength and success— they are above morality, above criticism. It seems then, that it is not what you do, but how you do it and what you call it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Not only the brave get killed, but the brave have a better chance of it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Good God, what a mess of draggle-tail impulses a man is — and a woman too, I guess.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "… we've got so many laws you can't breathe without breaking something.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The things everyone knows are most likely to be wrong.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Like most modern people, I don't believe in prophecy or magic and then spend half my time practicing it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A crime is something someone else commits.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A secret's a terribly lonesome thing.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "There's nobody as lonely as an all-married man.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Such is the prestige of the Nobel award and of this place where I stand that I am impelled, not to squeak like a grateful and apologetic mouse, but to roar like a lion out of pride in my profession and in the great and good men who have practiced it through the ages.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Literature is as old as speech. It grew out of human need for it, and it has not changed except to become more needed.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Humanity has been passing through a gray and desolate time of confusion. My great predecessor, William Faulkner, speaking here, referred to it as a tragedy of universal fear so long sustained that there were no longer problems of the spirit, so that only the human heart in conflict with itself seemed worth writing about.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Faulkner, more than most men, was aware of human strength as well as of human weakness. He knew that the understanding and the resolution of fear are a large part of the writer's reason for being.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The ancient commission of the writer has not changed. He is charged with exposing our many grievous faults and failures, with dredging up to the light our dark and dangerous dreams for the purpose of improvement.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The writer is delegated to declare and to celebrate man's proven capacity for greatness of heart and spirit — for gallantry in defeat — for courage, compassion and love. In the endless war against weakness and despair, these are the bright rally-flags of hope and of emulation. I hold that a writer who does not passionately believe in the perfectibility of man, has no dedication nor any membership in literature.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "We have usurped many of the powers we once ascribed to God. Fearful and unprepared, we have assumed lordship over the life or death of the whole world—of all living things. The danger and the glory and the choice rest finally in man. The test of his perfectibility is at hand. Having taken Godlike power, we must seek in ourselves for the responsibility and the wisdom we once prayed some deity might have. Man himself has become our greatest hazard and our only hope. So that today, St. John the apostle may well be paraphrased: In the end is the Word, and the Word is Man — and the Word is with Men.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A journey is like marriage. The certain way to be wrong is to think you control it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "When I was very young and the urge to be someplace was on me, I was assured by mature people that maturity would cure this itch. When years described me as mature, the remedy prescribed was middle age. In middle age I was assured that greater age would calm my fever and now that I am fifty-eight perhaps senility will do the job. Nothing has worked… In other words, I don’t improve, in further words, once a bum always a bum. I fear the disease is incurable.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A kind of second childhood falls on so many men. They trade their violence for the promise of a small increase of life span. In effect, the head of the house becomes the youngest child. And I have searched myself for this possibility with a kind of horror. For I have always lived violently, drunk hugely, eaten too much or not at all, slept around the clock or missed two nights of sleeping, worked too hard and too long in glory, or slobbed for a time in utter laziness. I’ve lifted, pulled, chopped, climbed, made love with joy and taken my hangovers as a consequence, not as a punishment. I did not want to surrender fierceness for a small gain in yardage. My wife married a man; I saw no reason why she should inherit a baby.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The techniques of opening conversation are universal. I knew long ago and rediscovered that the best way to attract attention, help, and conversation is to be lost. A man who seeing his mother starving to death on a path kicks her in the stomach to clear the way, will cheerfully devote several hours of his time giving wrong directions to a total stranger who claims to be lost.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "When the virus of restlessness begins to take possession of a wayward man, and the road away from Here seems broad and straight and sweet, the victim must first find himself a good and sufficient reason for going.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "And now, our submarines are armed with mass murder, our silly, only way of deterring mass murder.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A sad soul can kill you quicker, far quicker, than a germ.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Oh, we can populate the dark with horrors, even we who think ourselves informed and sure, believing nothing we cannot measure or weigh. I know beyond all doubt that the dark things crowding in on me either did not exist or were not dangerous to me, and still I was afraid.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The mountains of things we throw away are much greater than the things we use. In this, if in no other way, we can see the wild and reckless exuberance of our production, and waste seems to be the index.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The new American finds his challenge and his love in the traffic-choked streets, skies nested in smog, choking with the acids of industry, the screech of rubber and houses leashed in against one another while the townlets wither a time and die. This is not offered in criticism but only as observation. And I am sure that, as all pendulums reverse their swing, so eventually will the swollen cities rupture like dehiscent wombs and disperse their children back to the countryside.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Even while I protest the assembly-line production of our food, our songs, our language, and eventually our souls, I know that it was a rare home that baked good bread in the old days. Mother’s cooking was with rare exceptions poor, that good unpasteurized milk touched only by flies and bits of manure crawled with bacteria, the healthy old-time life was riddled with aches, sudden death from unknown causes, and that sweet local speech I mourn was the child of illiteracy and ignorance. It is the nature of a man as he grows older, a small bridge in time, to protest against change, particularly change for the better.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I am in love with Montana. For other states I have admiration, respect, recognition, even some affection, but with Montana it is love.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I guess this is why I hate governments. It is always the rule, the fine print, carried out by the fine print men. There's nothing to fight, no wall to hammer with frustrated fists.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "This monster of a land, this mightiest of nations, this spawn of the future, turns out to be the macrocosm of microcosm me.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The Mojave is a big desert and a frightening one. It’s as though nature tested a man for endurance and constancy to prove whether he was good enough to get to California.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "There used to be a thing or a commodity we put great store by. It was called the People. Find out where the People have gone. I don’t mean the square-eyed toothpaste-and-hair-dye people or the new-car-or-bust people, or the success-and-coronary people. Maybe they never existed, but if there ever were the People, that’s the commodity the Declaration was talking about, and Mr. Lincoln.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "He wasn't involved with a race that could build a thing it had to escape from.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I wonder why progress looks so much like destruction.", Author = "John Steinbeck" },
        };
    }
}